import {CATEGORIES,money,preciseMoney,compact,sum,escapeHTML as e,parseDate,detectMapping,parseRows,reconcile,hash,effective,mergeTransactions,monthsBetween,grouped,stats,recurring} from './core.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const PATHS={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',transactions:'<path d="M5 6h14M5 12h14M5 18h14"/><path d="m16 3 3 3-3 3M8 15l-3 3 3 3"/>',patterns:'<path d="M4 20V9m6 11V4m6 16v-7m6 7H2"/>',card:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20M6 15h4"/>',data:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',in:'<path d="M19 5 5 19M5 7v12h12"/>',out:'<path d="M5 19 19 5M7 5h12v12"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',review:'<path d="m12 3 10 18H2Z"/><path d="M12 9v5M12 17h.01"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>'};
const icon=name=>`<i data-icon="${name}"></i>`;
function icons(){ $$('i[data-icon]').forEach(el=>{el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${PATHS[el.dataset.icon]||PATHS.info}</svg>`;});}
const KEY='hardik-spend-insights-v1',PAGES={overview:'Overview',transactions:'Transactions',patterns:'Patterns',planner:'Card fit',data:'Statements'};
let seed,db,importState=null,toastTimer;
let state={page:'overview',from:'',to:'',category:'all',chartMode:'cashflow',mix:'all',search:'',direction:'all',onlyReview:false,min:'',max:'',pageIndex:0,sort:'newest',planCats:Object.keys(CATEGORIES).filter(c=>CATEGORIES[c].card),annualSpend:null,pointValue:.5,fee:10000,gst:18,waiver:800000,bonusQuarters:0,rent:0};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));$('#save-status').textContent='Saved on this browser';}catch(err){$('#save-status').textContent='Changes in memory only';toast('Browser storage is full or disabled. Download a backup to keep your edits.');}}
function all(){return db.transactions.map(t=>effective(t,db.overrides,db.rules));}
function bounds(){const ds=db.transactions.map(t=>t.date).sort();return[ds[0]||'',ds.at(-1)||''];}
function resetDates(){[state.from,state.to]=bounds();state.category='all';state.pageIndex=0;}
function rows(){return all().filter(t=>(!state.from||t.date>=state.from)&&(!state.to||t.date<=state.to)&&(state.category==='all'||t.category===state.category));}
function dateLabel(d,year=true){if(!d)return'—';return new Date(d+'T00:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',...(year?{year:'numeric'}:{}),timeZone:'UTC'});}
function monthLabel(m,year=false){return new Date(m+'-01T00:00:00Z').toLocaleDateString('en-IN',{month:'short',...(year?{year:'2-digit'}:{}),timeZone:'UTC'});}
const percent=(a,b)=>b?(a/b*100).toFixed(1)+'%':'0%';
function options(values,selected){return values.map(v=>`<option value="${e(v)}" ${v===selected?'selected':''}>${e(v)}</option>`).join('');}
function catOptions(selected){return options(Object.keys(CATEGORIES),selected);}
function heading(title,subtitle,eyebrow='YOUR MONEY, IN VIEW'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="period-stamp">${dateLabel(state.from)} — ${dateLabel(state.to)}</div></div>`;}
function filters(){return `<div class="filters"><span class="filter-label">Period</span><input aria-label="From date" type="date" id="filter-from" value="${e(state.from)}"><span class="filter-label">to</span><input aria-label="To date" type="date" id="filter-to" value="${e(state.to)}"><select aria-label="Filter category" id="filter-category"><option value="all">All categories</option>${catOptions(state.category)}</select><button class="reset" data-action="reset-filters">Reset filters</button><span class="filtered-note">${rows().length.toLocaleString('en-IN')} transactions in view</span></div>`;}
function panelHead(title,subtitle='',right=''){return `<div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${right}</div>`;}
function metric(title,value,detail,which,featured=false){return `<article class="metric ${featured?'featured':''}"><div class="metric-title">${title}${icon(which)}</div><div class="metric-value" title="${e(value)}">${value}</div><small>${detail}</small></article>`;}
function monthSeries(ts){return monthsBetween(state.from,state.to).slice(-36).map(key=>{const list=ts.filter(t=>t.date.startsWith(key));return {key,debit:sum(list.filter(t=>t.account==='bank'),'debit'),credit:sum(list.filter(t=>t.account==='bank'),'credit'),expense:sum(list.filter(t=>CATEGORIES[t.category]?.expense),'debit')};});}
function chart(ts){const data=monthSeries(ts);if(!data.length)return '<div class="empty">Import a statement to see monthly trends.</div>';const cash=state.chartMode==='cashflow',max=Math.max(1,...data.map(m=>cash?Math.max(m.debit,m.credit):m.expense));const w=680,h=219,left=43,base=181,usable=160,space=(w-left-7)/data.length,bw=Math.min(15,space*.27);let svg=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Monthly ${cash?'bank cash flow':'identified purchases'}; select a month to filter">`;
 for(let k=0;k<=4;k++){const y=base-usable*k/4;svg+=`<line class="tick" x1="${left}" x2="${w}" y1="${y}" y2="${y}"/><text x="${left-8}" y="${y+3}" text-anchor="end">${k===0?'0':compact(max*k/4)}</text>`;}
 data.forEach((m,i)=>{const x=left+space*i+space/2,values=cash?[[m.credit,'#b9c99f',x-bw-2],[m.debit,'#486a50',x+2]]:[[m.expense,'#7c9b67',x-bw/2]];svg+=`<g class="month-hit" data-month="${m.key}" role="button" tabindex="0" aria-label="Filter to ${monthLabel(m.key,true)}"><title>${monthLabel(m.key,true)}: ${cash?'Credits '+money(m.credit)+', debits '+money(m.debit):'Identified purchases '+money(m.expense)}</title><rect x="${left+i*space}" y="10" width="${space}" height="198" fill="transparent"/>`;values.forEach(([value,color,bx])=>{const height=value/max*usable;svg+=`<rect x="${bx}" y="${base-height}" width="${bw}" height="${Math.max(value?2:0,height)}" rx="2" fill="${color}"/>`;});svg+=`<text x="${x}" y="${base+17}" text-anchor="middle">${monthLabel(m.key)}</text><text x="${x}" y="${base+29}" text-anchor="middle" style="font-size:7px;fill:#b0b8a4">${m.key.slice(2,4)}</text></g>`;});return svg+'</svg>';}
function categoryList(ts,limit=7,expenseOnly=false){const groups=grouped(ts.filter(t=>t.debit>0&&(!expenseOnly||CATEGORIES[t.category]?.expense)),'category'),total=sum(groups,'total');if(!groups.length)return '<div class="empty">No debit transactions in this view.</div>';return `<div class="category-topline"><div class="category-total">${money(total)}</div><small>${expenseOnly?'identified purchases':'all debit categories'}</small></div><div class="category-list">${groups.slice(0,limit).map(g=>`<button class="category-row" data-category="${e(g.key)}" title="Filter ${e(g.key)}"><span class="dot" style="background:${CATEGORIES[g.key]?.color||'#aaa'}"></span><span class="label">${e(g.key)}<span class="bar-track" style="display:block"><span class="bar-fill" style="display:block;width:${g.total/total*100}%;background:${CATEGORIES[g.key]?.color||'#aaa'}"></span></span></span><strong>${money(g.total)}<span class="share">${percent(g.total,total)}</span></strong></button>`).join('')}</div>${groups.length>limit?`<p class="panel-note" style="margin-top:16px">${groups.length-limit} more categories. View Transactions to explore all.</p>`:''}`;}
function merchants(ts,limit=6){const gs=grouped(ts.filter(t=>t.debit>0&&CATEGORIES[t.category]?.expense),'merchant').slice(0,limit);return gs.length?gs.map(g=>`<div class="merchant-row"><div class="merchant-letter">${e(g.key.slice(0,1))}</div><div><b>${e(g.key)}</b><small>${g.count} payments · ${e(g.rows[0].category)}</small></div><div class="value">${money(g.total)}<small>${money(g.total/g.count)} average</small></div></div>`).join(''):'<div class="empty">Categorize purchases to see merchants.</div>';}
function overview(ts){const s=stats(ts),property=sum(ts.filter(t=>t.category==='Property payments'),'debit'),invest=sum(ts.filter(t=>t.category==='Investments & saving'),'debit'),largestReview=grouped(ts.filter(t=>t.review&&t.debit),'merchant')[0],net=s.bankCredit-s.bankDebit;
 return heading('Your year, at a glance.','A view of your account activity, with purchases, transfers and investments shown separately.')+filters()+`<div class="metrics">${metric('Bank money out',money(s.bankDebit),'All bank debits, including transfers and investments','out',true)}${metric('Identified purchases',money(s.expense),`${s.expenseCount} suggested expense transactions · incomplete until review`,'card')}${metric('Bank money in',money(s.bankCredit),'All credits · includes transfers, refunds and salary','in')}${metric('Outflow to review',money(s.unresolved),`${s.reviewCount} debits with an unclear purpose`,'review')}</div>
 <div class="two-col"><section class="panel">${panelHead('Monthly activity','Select a bar to explore that month.',`<div class="segmented"><button data-chart="cashflow" class="${state.chartMode==='cashflow'?'active':''}">Cash flow</button><button data-chart="spending" class="${state.chartMode==='spending'?'active':''}">Purchases</button></div>`)}${chart(ts)}<div class="legend">${state.chartMode==='cashflow'?'<span><i class="dot" style="background:#b9c99f"></i>Bank credits</span><span><i class="dot" style="background:#486a50"></i>Bank debits</span>':'<span><i class="dot" style="background:#7c9b67"></i>Identified purchases</span>'}<span class="right">Edge months may be partial</span></div></section>
 <section class="panel">${panelHead('Where money went','Select a category to filter.',`<div class="segmented"><button data-mix="all" class="${state.mix==='all'?'active':''}">All outflow</button><button data-mix="expense" class="${state.mix==='expense'?'active':''}">Purchases</button></div>`)}${categoryList(ts,6,state.mix==='expense')}</section></div>
 <div class="insight-strip"><div class="insight-icon">${icon('spark')}</div><div><h3>Account outflow is broader than everyday spending</h3><p>${money(property)} is labelled as property payments and ${money(invest)} as investment/saving mandates, based on narration. Both are excluded from identified purchases. Review unclear payments before using the total for card planning.</p></div><button class="button" data-page-link="planner">Explore card fit ${icon('arrow')}</button></div>
 <div class="two-col equal"><section class="panel">${panelHead('Your familiar merchants','Largest identifiable purchase merchants.',`<button class="text-link" data-page-link="transactions">View all</button>`)}${merchants(ts)}</section><section class="panel">${panelHead('A few things worth reviewing','Small actions that improve your spending picture.')}<div class="mini-stats"><div class="mini-stat"><strong>${money(s.cardSettlements)}</strong><small>Credit card settlements. Upload card statements for the underlying purchase detail.</small></div><div class="mini-stat"><strong>${money(net)}</strong><small>Net bank cash movement: credits minus debits. This is not a savings or income measure.</small></div></div>${largestReview?`<div class="review-prompt"><b>${e(largestReview.key)}</b> accounts for ${money(largestReview.total)} in unclear outflow across ${largestReview.count} payments. A merchant correction can update matching payments together.</div>`:''}<button class="button" style="margin-top:17px" data-action="review">Review categories ${icon('arrow')}</button><p class="panel-note" style="margin-top:14px">Every category is a suggestion from the transaction description. You can change any category or confirm a transfer.</p></section></div>`;
}
function filteredTransactions(ts){return ts.filter(t=>(!state.search||(t.description+' '+t.merchant+' '+t.category+' '+t.source).toLowerCase().includes(state.search.toLowerCase()))&&(state.direction==='all'||(state.direction==='debit'?t.debit>0:t.credit>0))&&(!state.onlyReview||t.review&&t.debit>0)&&(!state.min||(t.debit+t.credit)>=+state.min)&&(!state.max||(t.debit+t.credit)<=+state.max)).sort((a,b)=>state.sort==='largest'?(b.debit+b.credit)-(a.debit+a.credit):state.sort==='oldest'?a.date.localeCompare(b.date)||a.row-b.row:b.date.localeCompare(a.date)||b.row-a.row);}
function transactions(ts){const list=filteredTransactions(ts),size=35,maxPage=Math.max(0,Math.ceil(list.length/size)-1);state.pageIndex=Math.min(state.pageIndex,maxPage);const shown=list.slice(state.pageIndex*size,(state.pageIndex+1)*size);
return heading('Every payment has a story.','Search, filter and correct suggested categories. Use a transaction’s detail button to apply a category to the same merchant.')+filters()+`<section class="panel table-panel"><div class="table-heading">${panelHead('Transaction explorer',`${list.length.toLocaleString('en-IN')} matches · Debits ${money(sum(list,'debit'))} · Credits ${money(sum(list,'credit'))}`,`<button class="button small" data-action="export">${icon('download')}Export visible</button>`)}</div><div class="search-tools"><input id="tx-search" type="search" placeholder="Search merchant, description or source…" value="${e(state.search)}" aria-label="Search transactions"><select id="tx-direction" aria-label="Transaction direction"><option value="all">Debits & credits</option><option value="debit" ${state.direction==='debit'?'selected':''}>Debits only</option><option value="credit" ${state.direction==='credit'?'selected':''}>Credits only</option></select><select id="tx-sort" aria-label="Sort transactions"><option value="newest">Newest first</option><option value="oldest" ${state.sort==='oldest'?'selected':''}>Oldest first</option><option value="largest" ${state.sort==='largest'?'selected':''}>Largest first</option></select><input id="tx-min" type="number" min="0" placeholder="Min ₹" value="${e(state.min)}" aria-label="Minimum transaction amount"><input id="tx-max" type="number" min="0" placeholder="Max ₹" value="${e(state.max)}" aria-label="Maximum transaction amount"><label><input id="tx-review" type="checkbox" ${state.onlyReview?'checked':''}>Needs review</label></div><div class="table-scroll"><table><thead><tr><th>Date</th><th>Merchant / counterparty</th><th>Category</th><th>Status</th><th style="text-align:right">Debit</th><th style="text-align:right">Credit</th><th></th></tr></thead><tbody>${shown.map(t=>`<tr><td class="date">${dateLabel(t.date)}</td><td><span class="merchant-name" title="${e(t.merchant)}">${e(t.merchant)}</span><span class="description" title="${e(t.description)}">${e(t.description)}</span></td><td><select aria-label="Category for ${e(t.merchant)} on ${t.date}" data-tx-category="${t.id}">${catOptions(t.category)}</select></td><td><span class="pill ${t.review?'warning':t.classification==='Edited'?'manual':''}">${t.review?'Review':t.classification}</span></td><td class="num">${t.debit?preciseMoney(t.debit):'—'}</td><td class="num amount-credit">${t.credit?preciseMoney(t.credit):'—'}</td><td><button class="row-info" data-detail="${t.id}" aria-label="Details for ${e(t.merchant)}">${icon('info')}</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">No transactions match these filters.</div></td></tr>'}</tbody></table></div><div class="pagination"><span>${list.length?state.pageIndex*size+1:0}–${Math.min((state.pageIndex+1)*size,list.length)} of ${list.length.toLocaleString('en-IN')} transactions</span><div class="buttons"><button class="button small" data-page-step="-1" ${state.pageIndex===0?'disabled':''}>Previous</button><button class="button small" data-page-step="1" ${state.pageIndex===maxPage?'disabled':''}>Next</button></div></div></section>`;}
function patterns(ts){const rec=recurring(ts),months=monthsBetween(state.from,state.to).slice(-18),cats=grouped(ts.filter(t=>t.debit&&CATEGORIES[t.category]?.expense),'category'),max=Math.max(1,...cats.flatMap(c=>months.map(m=>sum(c.rows.filter(t=>t.date.startsWith(m)),'debit'))));
 const subscriptions=ts.filter(t=>t.category==='Subscriptions'&&t.debit),food=ts.filter(t=>['Dining & food','Groceries'].includes(t.category)&&t.debit);
return heading('See what repeats.','Explore monthly habits and recurring-payment candidates. Similar amounts are a clue, not proof of a subscription.')+filters()+`<div class="metrics">${metric('Digital subscriptions',money(sum(subscriptions,'debit')),`${subscriptions.length} identified payments in this period`,'data',true)}${metric('Food & groceries',money(sum(food,'debit')),`${food.length} identified payments in this period`,'card')}${metric('Repeat-payment candidates',String(rec.length),'Seen in at least three calendar months','patterns')}${metric('Distinct purchase merchants',String(new Set(ts.filter(t=>t.debit&&CATEGORIES[t.category]?.expense).map(t=>t.merchant)).size),'Based on normalized merchant names','transactions')}</div><section class="panel">${panelHead('The shape of your spending','Identified purchase categories by month. Darker cells show a larger amount.')}<div class="table-scroll"><div class="heatmap" style="--months:${months.length||1}"><div class="heat-row head"><span>Category</span>${months.map(m=>`<span>${monthLabel(m,true)}</span>`).join('')}</div>${cats.map(c=>`<div class="heat-row"><span>${e(c.key)}</span>${months.map(m=>{const v=sum(c.rows.filter(t=>t.date.startsWith(m)),'debit');return `<button class="heat-cell" style="background:rgba(124,155,103,${v?.08+.65*v/max:.025})" data-heat-month="${m}" data-heat-category="${e(c.key)}" title="${e(c.key)} · ${monthLabel(m,true)}: ${money(v)}">${v?compact(v):'—'}</button>`;}).join('')}</div>`).join('')}</div></div><p class="panel-note" style="margin-top:17px">${months.length===18?'Showing the latest 18 months. ':''}The first and last month may be partial. Unclear transfers and merchant payments are excluded until categorized.</p></section><h2 class="section-title">Repeat-payment candidates</h2><div class="recurring-grid">${rec.slice(0,12).map(g=>`<article class="recurring-card"><div class="row"><div class="merchant-letter">${e(g.key[0])}</div><span class="pill">${g.months} months</span></div><div class="name">${e(g.key)}</div><div class="amount">${money(g.median)}</div><div class="meta">Typical payment · ${g.count} payments<br>${money(g.total)} total in this period<br>${e(g.rows[0].category)}</div><div class="month-dots" aria-label="Active months">${months.map(m=>`<span class="${g.rows.some(t=>t.date.startsWith(m))?'filled':''}" title="${monthLabel(m,true)}"></span>`).join('')}</div></article>`).join('')||'<div class="empty">No repeat-amount candidates found in this date range.</div>'}</div><div class="note-box">A candidate needs payments in at least three months and at least 65% of its amounts within 15% of the median. Regular cafe purchases can also match; this does not imply an automatic debit mandate.</div>`;}
function planner(ts){const potential=ts.filter(t=>t.debit>0&&state.planCats.includes(t.category)),observed=sum(potential,'debit'),spend=state.annualSpend===null?observed:state.annualSpend,maxQ=Math.min(4,Math.floor(spend/400000));state.bonusQuarters=Math.min(state.bonusQuarters,maxQ);const points=Math.floor(spend/150)*5,bonus=state.bonusQuarters*10000,gross=(points+bonus)*state.pointValue,fee=spend>=state.waiver?0:state.fee*(1+state.gst/100),rentFee=state.rent*12*.01*(1+state.gst/100),net=gross-fee-rentFee,gap=Math.max(0,state.waiver-spend),pct=Math.min(100,spend/state.waiver*100),s=stats(ts);
return heading('Make the annual fee earn its place.','An editable Diners Black Metal scenario grounded in the purchases you can identify. Bank narrations do not contain card acceptance or merchant-category codes.','CREDIT CARD PLANNING')+filters()+`<div class="insight-strip warning"><div class="insight-icon">${icon('info')}</div><div><h3>Use this as a scenario, not confirmed qualifying spend</h3><p>${money(s.unresolved)} of debit outflow still needs review. ${money(s.cardSettlements)} in credit-card settlements hides the underlying purchases. Rent, transfers, property payments, investments and cash withdrawals are excluded from the default spending estimate.</p></div></div><div class="planner-grid"><section class="panel">${panelHead('Start with the spending you can identify','Choose candidate categories, then adjust the annual scenario.')}<div class="category-choices">${Object.keys(CATEGORIES).filter(c=>CATEGORIES[c].expense&&c!=='Rent'&&c!=='Taxes & fees').map(c=>`<label><input type="checkbox" data-plan-category="${e(c)}" ${state.planCats.includes(c)?'checked':''}>${e(c)}</label>`).join('')}</div><div class="note-box">Selected source spend: <b>${money(observed)}</b>. These payments could potentially move to a card if the merchant accepts it and the transaction qualifies. The date window is not annualized.</div><div class="form-grid"><label class="field">Annual eligible spend to model (₹)<input id="plan-spend" type="number" min="0" step="1000" value="${spend.toFixed(0)}"><small>Use about 12 months of spending. Edit this for your future estimate.</small></label><label class="field">Reward point value (₹)<select id="plan-point"><option value="0.5" ${state.pointValue===.5?'selected':''}>0.50 · products / vouchers ceiling</option><option value="0.3" ${state.pointValue===.3?'selected':''}>0.30 · conservative scenario</option><option value="1" ${state.pointValue===1?'selected':''}>1.00 · flights / hotels</option></select><small>Count only redemption value you expect to use.</small></label><label class="field">Annual fee before GST (₹)<input type="number" id="plan-fee" min="0" value="${state.fee}"></label><label class="field">GST on fees (%)<input type="number" id="plan-gst" min="0" max="100" value="${state.gst}"></label><label class="field">Annual spend waiver target (₹)<input type="number" id="plan-waiver" min="1" value="${state.waiver}"></label><label class="field">Verified ₹4L calendar quarters<select id="plan-quarters">${Array.from({length:maxQ+1},(_,i)=>`<option value="${i}" ${state.bonusQuarters===i?'selected':''}>${i} qualifying quarter${i===1?'':'s'}</option>`).join('')}</select><small>Manual choice. Your annual amount alone does not prove a quarterly milestone.</small></label><label class="field full-width">Optional monthly rent through card (₹)<input type="number" id="plan-rent" min="0" value="${state.rent}"><small>Models a 1% bank rent fee plus GST, before platform charges. Rent is not added to qualifying spend or reward points here.</small></label></div><button class="text-link" style="margin-top:16px" data-action="plan-reset">Use selected source spend again</button><details class="disclosure"><summary>Assumptions and official terms</summary><p>Benchmark: 5 points per ₹150 of eligible retail spending, ₹8 lakh annual renewal waiver, ₹10,000 fee before tax, and 10,000 bonus points for each qualifying ₹4 lakh calendar quarter. Products and vouchers offer up to ₹0.50 per point; flights and hotels offer ₹1 per point. Defaults checked 15 Oct 2026.</p><p>This approximation excludes SmartBuy multipliers, welcome memberships, category caps, transaction-level rounding, reward exclusions, partner charges and redemption availability. A lower-fee card can also earn rewards, so the net figure is not the advantage over alternatives. The first-year joining fee can still apply even if the following renewal is waived.</p><p>Rent earns no points. Maintenance payment treatment and fee-waiver eligibility must be verified with HDFC for the payment route. <a class="source-link" href="https://www.hdfc.bank.in/credit-cards/diners-club-black-metal-edition-credit-card" target="_blank" rel="noopener">HDFC card benefits</a> · <a class="source-link" href="https://www.hdfc.bank.in/credit-cards/diners-club-black-metal-edition-credit-card/fees-and-charges" target="_blank" rel="noopener">Fees and charges</a></p></details></section><div><section class="panel planner-result"><div class="eyebrow" style="color:#a9bf94">YOUR EDITABLE SCENARIO</div><h2>Potential annual card spend</h2><div class="big">${money(spend)}</div><div class="sub">${money(gap)} ${gap?'below the renewal-waiver target':'remaining to target'}</div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><div class="row"><span>${pct.toFixed(0)}% of target</span><b>${money(state.waiver)}</b></div><hr><div class="row"><span>Base reward points, approximate</span><b>${points.toLocaleString('en-IN')}</b></div><div class="row"><span>Quarterly bonus points, selected</span><b>${bonus.toLocaleString('en-IN')}</b></div><div class="row"><span>Modelled reward value</span><b>${money(gross)}</b></div><div class="row"><span>Renewal fee incl. entered GST</span><b>− ${money(fee)}</b></div><div class="row"><span>Optional yearly rent fee estimate</span><b>− ${money(rentFee)}</b></div><hr><div class="sub">Reward value less modelled fees</div><div class="big" style="font-size:32px;margin-top:12px">${money(net)}</div><p class="footnote">${net<0?'Rewards in this scenario do not cover the modelled fees.':'A positive result means estimated rewards exceed the modelled fees. Compare with rewards from a lower-fee card too.'} This is a planning estimate, not a guarantee of rewards or waiver eligibility.</p></section><div class="note-box">The ₹8 lakh benchmark is approximately <b>₹66,667 per month</b> of qualifying spend. Adding a costly payment route just to meet a threshold can reduce the benefit.</div></div></div>`;}
function dataPage(){return heading('A statement today. A habit tomorrow.','Import new statements, merge overlapping periods and keep your category corrections. Your original account number and UPI addresses are omitted from this dashboard.','YOUR DATA')+`<div class="two-col"><section class="panel">${panelHead('Import another statement','Numbers, Excel, CSV and TSV. Restore a dashboard backup with JSON.')}<button class="upload-area" data-action="upload" style="width:100%">${icon('upload')}<h3>Choose a statement or drop it here</h3><p>.numbers · .xlsx · .xls · .csv · .tsv · backup .json<br>Parsed in your browser. No upload to a server.</p></button><div class="note-box">For the same account, use the same account label when importing. Exact overlapping transactions are skipped. Different accounts can share a date and amount without being treated as duplicates.</div><div class="data-actions"><button class="button" data-action="backup">${icon('download')}Download backup</button><button class="button" data-action="export">Export transaction CSV</button></div></section><section class="panel">${panelHead('About this analysis','A few definitions that keep the numbers useful.')}<p class="small-muted"><b>Bank cash flow</b> includes all debits and credits from accounts labelled as bank accounts. Imported credit-card rows are excluded from these cash-flow totals.</p><p class="small-muted"><b>Identified purchases</b> includes debit transactions assigned to expense categories, including insurance and taxes. Transfers, investments, property payments, cash withdrawals and card bill payments are excluded.</p><p class="small-muted"><b>Review categories</b> are unclear transfers or merchant payments. They are not assumed to be purchases. You can categorize them or confirm that they are transfers.</p><p class="small-muted"><b>Credits are gross inflows.</b> Merchant refunds appear separately and are not automatically netted against purchases. Bank settlements cannot reveal what you bought on a credit card.</p></section></div><section class="panel">${panelHead('Imported statements',`${db.sources.length} source${db.sources.length===1?'':'s'} · ${db.transactions.length.toLocaleString('en-IN')} unique transactions in this browser`)}<div class="sources-list">${db.sources.map(s=>`<article class="source-card"><div><div class="source-name">${e(s.name)}</div><div class="source-meta">${e(s.accountKey||s.account)} · ${e(s.sheet||'Table')}<br>${dateLabel(s.from)} — ${dateLabel(s.to)} · ${s.count.toLocaleString('en-IN')} parsed rows${s.added!==undefined?` · ${s.added} added, ${s.duplicates||0} overlapping rows skipped`:''}</div><div class="source-totals"><span>Source debits<b>${money(s.debit)}</b></span><span>Source credits<b>${money(s.credit)}</b></span></div>${s.check?.available?`<details class="disclosure"><summary>Reconciliation and source details</summary><p>Running-balance checks: ${s.check.count}. Differences: ${s.check.errors.length}. Opening balance derived from the first transaction: ${preciseMoney(s.check.opening)}. Last stated balance: ${preciseMoney(s.check.closing)}.</p><p>Source totals include every parsed row in that file. Overlapping rows are skipped in dashboard totals, so source totals should not be added together.</p>${s.check.errors.length?`<p class="warning-text">Review the original statement near source rows ${s.check.errors.slice(0,8).map(x=>x.row).join(', ')} before relying on cash-flow totals. Transactions were preserved.</p>`:''}</details>`:'<p class="small-muted">Running-balance reconciliation unavailable: no bank balance column.</p>'}</div><span class="badge-check" style="${s.check?.errors?.length?'background:#faeee2;color:#ac7444':''}">${s.check?.available?s.check.errors.length?'Balance differences to review':'Running balances reconcile':'Imported without balance check'}</span></article>`).join('')||'<div class="empty">No statements. Import a file to begin.</div>'}</div></section><section class="panel" style="margin-top:20px">${panelHead('Storage and backup','The initial statement is part of this owner-private dashboard. Later uploads and edits stay in this browser.')}<p class="small-muted">Export a JSON backup to move your work to another browser. CSV exports include transactions but do not preserve categorization rules. Clearing browser storage can remove later imports. PDF imports are not supported; export a bank PDF to CSV/Excel first. Numbers support has been verified with your supplied statement; workbook structures can vary.</p><div class="data-actions"><button class="button" data-action="restore-original">Restore original statement</button><button class="button danger" data-action="clear">Clear dashboard in this browser</button></div></section>`;}
function render(){state.page=PAGES[location.hash.slice(1)]?location.hash.slice(1):state.page;const ts=rows();$('#page-label').textContent=PAGES[state.page];$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===state.page));const n=all().filter(t=>t.review&&t.debit).length;$('#nav-review').textContent=n?n.toLocaleString('en-IN'):'';
 $('#main').innerHTML=state.page==='overview'?overview(ts):state.page==='transactions'?transactions(ts):state.page==='patterns'?patterns(ts):state.page==='planner'?planner(ts):dataPage();icons();}
function navigate(page){state.page=page;location.hash=page;render();window.scrollTo({top:0,behavior:'smooth'});}
function monthFilter(month,category=null){const[lo,hi]=bounds();state.from=month+'-01';const[y,m]=month.split('-').map(Number);state.to=new Date(Date.UTC(y,m,0)).toISOString().slice(0,10);if(lo&&state.from<lo)state.from=lo;if(hi&&state.to>hi)state.to=hi;if(category)state.category=category;state.pageIndex=0;render();}
function download(name,content,type){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csvCell(v){let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportCSV(){const list=state.page==='transactions'?filteredTransactions(rows()):rows(),header=['Date','Merchant','Description','Category','Debit INR','Credit INR','Balance INR','Account label','Source','Classification'];const lines=list.map(t=>[t.date,t.merchant,t.description,t.category,t.debit,t.credit,t.balance??'',t.accountKey,t.source,t.classification]);download(`spend-insights-${state.from||'all'}-${state.to||'all'}.csv`,'\uFEFF'+[header,...lines].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast(`${list.length} transactions exported.`);}
function detail(id){const t=all().find(x=>x.id===id);if(!t)return;$('#detail-body').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">TRANSACTION DETAIL</div><h2 id="detail-title">${e(t.merchant)}</h2><p>${dateLabel(t.date)} · ${e(t.accountKey)}</p></div><button class="close-dialog" data-close="detail-dialog" aria-label="Close detail">×</button></div><div class="detail-grid"><div><small>Debit</small><span>${preciseMoney(t.debit)}</span></div><div><small>Credit</small><span>${preciseMoney(t.credit)}</span></div><div class="full"><small>Sanitized statement narration</small><div class="detail-description">${e(t.description)}</div></div><div class="full"><small>Category suggestion</small><span>${e(t.reason)}</span></div><div class="full"><small>Source</small><span>${e(t.source)} · spreadsheet row ${t.row}</span></div></div><label class="field">Category<select id="detail-category">${catOptions(t.category)}</select></label><div class="dialog-actions"><label><input type="checkbox" id="apply-merchant">Apply to all ${t.debit?'debit':'credit'} payments for this merchant</label><button class="button primary" data-save-detail="${id}">Save category</button></div><p class="panel-note" style="margin-top:15px">Saving also confirms the payment’s purpose. Merchant rules will apply to matching future imports. References and UPI addresses were removed from the narration.</p>`;$('#detail-dialog').showModal();icons();}
function validBackup(x){if(!x||x.version!==1||!Array.isArray(x.transactions)||!Array.isArray(x.sources)||!x.overrides||!x.rules)throw Error('This is not a Spend Insights backup.');if(x.transactions.length>100000)throw Error('This backup is too large.');for(const t of x.transactions){if(!parseDate(t.date)||typeof t.id!=='string'||typeof t.merchant!=='string'||typeof t.description!=='string'||!Object.hasOwn(CATEGORIES,t.category)||!Number.isFinite(t.debit)||!Number.isFinite(t.credit)||t.debit<0||t.credit<0||t.debit&&t.credit||!['bank','card'].includes(t.account))throw Error('This backup contains an invalid transaction.');}for(const c of [...Object.values(x.overrides),...Object.values(x.rules)])if(!Object.hasOwn(CATEGORIES,c))throw Error('The backup contains an unknown category.');return x;}
async function openFile(file){if(!file)return;if(file.size>20*1024*1024){toast('Choose a statement smaller than 20 MB.');return;}$('#import-body').innerHTML=`<div class="loading">Reading ${e(file.name)}…</div>`;$('#import-dialog').showModal();
try{if(/\.json$/i.test(file.name)){const restored=validBackup(JSON.parse(await file.text()));importState={backup:restored,name:file.name};$('#import-body').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">RESTORE A BACKUP</div><h2 id="import-title">Bring your dashboard back.</h2><p>${e(file.name)}</p></div><button class="close-dialog" data-close="import-dialog" aria-label="Close import">×</button></div><div class="note-box">This backup contains ${restored.transactions.length.toLocaleString('en-IN')} transactions, ${restored.sources.length} statements and ${Object.keys(restored.rules).length} merchant rules. Restoring replaces the dashboard stored in this browser.</div><div class="dialog-actions"><button class="button" data-close="import-dialog">Cancel</button><button class="button primary" data-action="confirm-backup">Restore backup</button></div>`;return;}
 if(!/\.(numbers|xlsx|xls|csv|tsv)$/i.test(file.name))throw Error('Choose a Numbers, Excel, CSV or TSV statement. PDF import is not supported.');
 const isText=/\.(csv|tsv)$/i.test(file.name);const workbook=XLSX.read(isText?await file.text():await file.arrayBuffer(),{type:isText?'string':'array',cellDates:true,raw:true});if(!workbook.SheetNames.length)throw Error('No readable table was found.');
 let bestName=workbook.SheetNames[0],bestScore=-1;for(const name of workbook.SheetNames){const rr=XLSX.utils.sheet_to_json(workbook.Sheets[name],{header:1,defval:null,raw:true}),d=detectMapping(rr);if(d.score>bestScore){bestName=name;bestScore=d.score;}}
 importState={workbook,name:file.name,sheet:bestName,account:'bank',accountKey:'Main bank',dateOrder:'DMY',sign:'debit-positive',mode:'merge'};selectImportSheet(bestName);renderImport();
}catch(err){$('#import-body').innerHTML=`<div class="dialog-head"><div><h2 id="import-title">We couldn’t read this file.</h2><p>Try exporting the statement from Numbers as Excel or CSV.</p></div><button class="close-dialog" data-close="import-dialog" aria-label="Close import">×</button></div><div class="error-box">${e(err.message||'The file format is not supported.')}</div><button class="button" data-close="import-dialog">Close</button>`;}}
function selectImportSheet(name){importState.sheet=name;importState.rows=XLSX.utils.sheet_to_json(importState.workbook.Sheets[name],{header:1,defval:null,raw:true});const d=detectMapping(importState.rows);importState.header=d.header;importState.map=d.map;importState.layout=d.map.amount>=0&&d.map.debit<0?'signed':'split';}
function previewImport(){const map={...importState.map};if(importState.layout==='split')map.amount=-1;else{map.debit=-1;map.credit=-1;}return parseRows(importState.rows,{...importState,map,source:importState.name,sourceId:'import-'+hash(importState.name+Date.now()),accountKey:importState.accountKey.trim()||'Main bank'});}
function renderImport(){const s=importState;if(s.backup)return;const headers=s.rows[s.header]||[],columnOptions=selected=>'<option value="-1">Not present</option>'+headers.map((h,i)=>`<option value="${i}" ${selected===i?'selected':''}>${i+1}: ${e(String(h??'(blank)').slice(0,58))}</option>`).join('');const result=previewImport();s.parsed=result;const ts=result.transactions,ds=ts.map(t=>t.date).sort(),check=reconcile(ts);s.check=check;const duplicate=mergeTransactions(db.transactions,ts).duplicate;const valid=s.map.date>=0&&s.map.description>=0&&(s.layout==='signed'?s.map.amount>=0:s.map.debit>=0||s.map.credit>=0)&&ts.length>0;
$('#import-body').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">IMPORT A STATEMENT</div><h2 id="import-title">Check the columns. Then explore.</h2><p>${e(s.name)} · original file stays on your device</p></div><button class="close-dialog" data-close="import-dialog" aria-label="Close import">×</button></div><div class="import-controls"><label class="field">Sheet / table<select data-import="sheet">${options(s.workbook.SheetNames,s.sheet)}</select></label><label class="field">Header row (1-based)<input data-import="header" type="number" min="1" max="${s.rows.length}" value="${s.header+1}"></label><label class="field">Account type<select data-import="account"><option value="bank">Bank account</option><option value="card" ${s.account==='card'?'selected':''}>Credit card statement</option></select></label><label class="field">Account label<input data-import="accountKey" value="${e(s.accountKey)}" maxlength="80"><small>Same label = same account for deduplication.</small></label><label class="field">Date format<select data-import="dateOrder"><option value="DMY">Day / month / year</option><option value="MDY" ${s.dateOrder==='MDY'?'selected':''}>Month / day / year</option></select></label><label class="field">Amount columns<select data-import="layout"><option value="split">Separate debit and credit</option><option value="signed" ${s.layout==='signed'?'selected':''}>One amount column</option></select></label></div><div class="mapping-grid">${[['date','Transaction date'],['description','Description / narration'],['balance','Running balance (optional)'],...(s.layout==='split'?[['debit','Debit / withdrawal'],['credit','Credit / deposit']]:[['amount','Amount'],['type','Debit / credit flag (optional)']])].map(([k,label])=>`<label>${label}<select data-map="${k}">${columnOptions(s.map[k])}</select></label>`).join('')}${s.layout==='signed'?`<label>When no debit / credit flag<select data-import="sign"><option value="debit-positive">Positive = purchase / debit</option><option value="credit-positive" ${s.sign==='credit-positive'?'selected':''}>Positive = deposit / credit</option></select></label>`:''}</div><div class="note-box"><b>${ts.length.toLocaleString('en-IN')} transactions</b> · ${money(sum(ts,'debit'))} debits · ${money(sum(ts,'credit'))} credits<br>${dateLabel(ds[0])} — ${dateLabel(ds.at(-1))} · ${duplicate} exact overlaps with existing data<br>${result.counts.nonTransactions} blank / non-transaction rows skipped · ${result.counts.invalid} invalid dated rows · ${result.counts.zero} zero-amount rows</div>${result.counts.invalid?`<div class="error-box">${result.counts.invalid} dated rows could not be imported. Verify the amount/date mapping and compare totals with the source before confirming.</div>`:''}${check.available&&check.errors.length?`<div class="error-box">${check.errors.length} running-balance differences were found. Check sort order and column mapping. Parsed transactions are preserved if you continue.</div>`:''}<div class="import-preview"><table><thead><tr><th>Date</th><th>Merchant / counterparty</th><th>Debit</th><th>Credit</th></tr></thead><tbody>${ts.slice(0,6).map(t=>`<tr><td>${dateLabel(t.date)}</td><td>${e(t.merchant)}</td><td>${money(t.debit)}</td><td>${money(t.credit)}</td></tr>`).join('')||'<tr><td colspan="4">No transactions found. Adjust the header row and mapped columns.</td></tr>'}</tbody></table></div><div class="dialog-actions"><label>Import mode<select data-import="mode" style="padding:8px;border:1px solid #dde3d5"><option value="merge">Merge, skipping overlaps</option><option value="replace" ${s.mode==='replace'?'selected':''}>Replace current transactions</option></select></label><button class="button" data-close="import-dialog">Cancel</button><button class="button primary" data-action="confirm-import" ${valid?'':'disabled'}>Import ${ts.length.toLocaleString('en-IN')} rows</button></div><p class="panel-note" style="margin-top:14px">Date + original narration + debit/credit + balance + account label identify overlaps. Repeated identical transactions within a statement are retained. Exports with altered narrations or missing balances may need manual review.</p>`;}
function confirmImport(){const s=importState,ts=s.parsed.transactions;if(!ts.length)return;const replacing=s.mode==='replace';if(replacing&&!confirm('Replace all current transactions with this statement? Your category rules will be kept.'))return;const result=mergeTransactions(replacing?[]:db.transactions,ts);if(!result.added){toast('Every transaction already exists. Nothing was added.');$('#import-dialog').close();return;}const ds=ts.map(t=>t.date).sort(),sourceId=ts[0].sourceId;const source={id:sourceId,name:s.name,sheet:s.sheet,account:s.account,accountKey:s.accountKey,count:ts.length,from:ds[0],to:ds.at(-1),debit:sum(ts,'debit'),credit:sum(ts,'credit'),check:s.check,added:result.added,duplicates:result.duplicate,skipped:s.parsed.counts,importedAt:new Date().toISOString().slice(0,10)};db.transactions=result.transactions;db.sources=replacing?[source]:[...db.sources,source];save();resetDates();$('#import-dialog').close();navigate('overview');toast(`${result.added} transactions added; ${result.duplicate} overlaps skipped.`);}
document.addEventListener('click',ev=>{const t=ev.target.closest('button,a,[data-month]');if(!t)return;if(t.dataset.close){$('#'+t.dataset.close).close();return;}if(t.dataset.pageLink){navigate(t.dataset.pageLink);return;}if(t.dataset.chart){state.chartMode=t.dataset.chart;render();return;}if(t.dataset.mix){state.mix=t.dataset.mix;render();return;}if(t.dataset.month){monthFilter(t.dataset.month);return;}if(t.dataset.heatMonth){monthFilter(t.dataset.heatMonth,t.dataset.heatCategory);navigate('transactions');return;}if(t.dataset.category){state.category=t.dataset.category;state.pageIndex=0;render();return;}if(t.dataset.pageStep){state.pageIndex+=+t.dataset.pageStep;render();return;}if(t.dataset.detail){detail(t.dataset.detail);return;}if(t.dataset.saveDetail){const tx=db.transactions.find(x=>x.id===t.dataset.saveDetail),cat=$('#detail-category').value;db.overrides[tx.id]=cat;if($('#apply-merchant').checked)db.rules[tx.merchant+'|'+(tx.debit?'debit':'credit')]=cat;save();$('#detail-dialog').close();render();toast('Category saved.');return;}
 switch(t.dataset.action){case'upload':$('#file-input').value='';$('#file-input').click();break;case'backup':download('spend-insights-backup.json',JSON.stringify(db,null,2),'application/json');toast('Backup downloaded.');break;case'export':exportCSV();break;case'reset-filters':resetDates();state.search='';state.direction='all';state.onlyReview=false;state.min='';state.max='';render();break;case'review':state.onlyReview=true;state.pageIndex=0;navigate('transactions');break;case'plan-reset':state.annualSpend=null;render();break;case'confirm-import':confirmImport();break;case'confirm-backup':db=importState.backup;save();resetDates();$('#import-dialog').close();navigate('overview');toast('Backup restored.');break;case'clear':if(confirm('Clear transactions and category edits in this browser? The original private statement can still be restored.')){db={version:1,transactions:[],sources:[],overrides:{},rules:{}};save();resetDates();render();toast('Dashboard cleared on this browser.');}break;case'restore-original':if(confirm('Restore the original statement and remove later imports and edits from this browser?')){db=structuredClone(seed);save();resetDates();render();toast('Original statement restored.');}break;}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.id==='file-input'){openFile(el.files[0]);return;}if(el.dataset.txCategory){db.overrides[el.dataset.txCategory]=el.value;save();render();toast('Category updated.');return;}if(el.dataset.map){importState.map[el.dataset.map]=+el.value;renderImport();return;}if(el.dataset.import){const k=el.dataset.import;if(k==='sheet')selectImportSheet(el.value);else if(k==='header'){importState.header=Math.max(0,Math.min(importState.rows.length-1,+el.value-1));importState.map=detectMapping([importState.rows[importState.header]]).map;}else{importState[k]=el.value;if(k==='account'&&['Main bank','Credit card'].includes(importState.accountKey))importState.accountKey=el.value==='bank'?'Main bank':'Credit card';}renderImport();return;}if(el.dataset.planCategory){state.planCats=el.checked?[...state.planCats,el.dataset.planCategory]:state.planCats.filter(c=>c!==el.dataset.planCategory);state.annualSpend=null;render();return;}const changes={'filter-from':'from','filter-to':'to','filter-category':'category','tx-direction':'direction','tx-sort':'sort','tx-min':'min','tx-max':'max'};if(changes[el.id]){state[changes[el.id]]=el.value;if(state.from&&state.to&&state.from>state.to){state.to=state.from;toast('End date adjusted to the start date.');}state.pageIndex=0;render();return;}if(el.id==='tx-review'){state.onlyReview=el.checked;state.pageIndex=0;render();return;}const plans={'plan-spend':'annualSpend','plan-point':'pointValue','plan-fee':'fee','plan-gst':'gst','plan-waiver':'waiver','plan-quarters':'bonusQuarters','plan-rent':'rent'};if(plans[el.id]){const val=Math.max(el.id==='plan-waiver'?1:0,Number(el.value)||0);state[plans[el.id]]=el.id==='plan-gst'?Math.min(100,val):val;render();}});
let searchTimer;document.addEventListener('input',ev=>{if(ev.target.id==='tx-search'){state.search=ev.target.value;state.pageIndex=0;clearTimeout(searchTimer);const cursor=ev.target.selectionStart;searchTimer=setTimeout(()=>{render();const el=$('#tx-search');if(el){el.focus();try{el.setSelectionRange(cursor,cursor);}catch{}}},180);}});
document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.dataset.month){ev.preventDefault();monthFilter(ev.target.dataset.month);}});
window.addEventListener('hashchange',()=>{state.page=PAGES[location.hash.slice(1)]?location.hash.slice(1):'overview';render();});
for(const id of ['import-dialog','detail-dialog'])$('#'+id).addEventListener('click',ev=>{if(ev.target===ev.currentTarget){const r=ev.currentTarget.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.currentTarget.close();}});
let dragDepth=0;document.addEventListener('dragenter',ev=>{if(!ev.dataTransfer?.types?.includes('Files'))return;ev.preventDefault();if(++dragDepth===1){const overlay=document.createElement('div');overlay.className='drop-overlay';overlay.id='drop-overlay';overlay.innerHTML='<div>Drop your statement<br><small style="font-size:13px;opacity:.7">Numbers, Excel, CSV or dashboard backup</small></div>';document.body.append(overlay);}});document.addEventListener('dragover',ev=>{if(ev.dataTransfer?.types?.includes('Files'))ev.preventDefault();});document.addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;$('#drop-overlay')?.remove();}});document.addEventListener('drop',ev=>{ev.preventDefault();dragDepth=0;$('#drop-overlay')?.remove();if(ev.dataTransfer?.files?.length)openFile(ev.dataTransfer.files[0]);});
async function init(){try{seed=validBackup(await(await fetch('seed.json',{cache:'no-store'})).json());db=structuredClone(seed);try{const saved=localStorage.getItem(KEY);if(saved)db=validBackup(JSON.parse(saved));}catch{toast('Saved browser data could not be read. The original statement is loaded.');}resetDates();state.page=PAGES[location.hash.slice(1)]?location.hash.slice(1):'overview';render();}catch(err){$('#main').innerHTML=`<div class="error-box">The dashboard could not load its initial data. ${e(err.message)} Refresh the page to try again.</div>`;}}
icons();await init();
